-- ============================================================================
-- Agentic AI-Powered Commercial Card Intelligence & Marketing Optimization
-- Platform — MySQL 8 schema (production deployment)
--
-- The offline demo runs the same tables in SQLite (src/db.py). Apply this
-- script to an empty MySQL database, then load the CSVs from data/ (or run
-- src/db.py:load_mysql with MYSQL_* env vars set).
--
-- Data is SYNTHETIC (generated by src/data_generation.py). Never load real
-- cardholder data without the compliance review in kb/KB-11.
-- ============================================================================

CREATE DATABASE IF NOT EXISTS card_intelligence
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE card_intelligence;

DROP TABLE IF EXISTS ab_test_daily;
DROP TABLE IF EXISTS campaigns;
DROP TABLE IF EXISTS transactions;
DROP TABLE IF EXISTS engagement_monthly;
DROP TABLE IF EXISTS cardholders;

CREATE TABLE cardholders (
    cardholder_id         INT PRIMARY KEY,
    company_name          VARCHAR(100) NOT NULL,
    industry              VARCHAR(50)  NOT NULL,
    region                VARCHAR(50)  NOT NULL,
    segment               VARCHAR(20)  NOT NULL,          -- SMB | Mid-Market | Large
    employees             DOUBLE       NOT NULL,
    tenure_months         DOUBLE       NOT NULL,
    annual_spend_baseline DECIMAL(14,2) NOT NULL,
    INDEX ix_card_segment (segment),
    INDEX ix_card_industry (industry)
) ENGINE=InnoDB;

CREATE TABLE engagement_monthly (
    cardholder_id      INT NOT NULL,
    month              CHAR(7) NOT NULL,                  -- 'YYYY-MM'
    month_index        INT NOT NULL,                      -- 0..23
    logins             INT NOT NULL,
    app_sessions       INT NOT NULL,
    email_clicks       INT NOT NULL,
    spend              DECIMAL(14,2) NOT NULL,
    txn_count          INT NOT NULL,
    engagement_score   DECIMAL(5,1) NOT NULL,             -- 0..100 (kb/KB-08)
    score_fwd3         DECIMAL(5,1) NULL,                 -- label look-ahead (training only)
    engagement_decline TINYINT NOT NULL,                  -- 1/0, -1 = not evaluable
    PRIMARY KEY (cardholder_id, month_index),
    INDEX ix_eng_month (month)
) ENGINE=InnoDB;

CREATE TABLE transactions (
    txn_id            CHAR(11) PRIMARY KEY,                -- 'TXN-0000001'
    cardholder_id     INT NOT NULL,
    txn_date          DATE NOT NULL,
    merchant_category VARCHAR(50) NOT NULL,
    amount            DECIMAL(14,2) NOT NULL,
    channel           VARCHAR(20) NOT NULL,                -- Online | In-Store
    rewards_rate      DECIMAL(6,4) NOT NULL,
    rewards_earned    DECIMAL(14,2) NOT NULL,
    INDEX ix_txn_card (cardholder_id),
    INDEX ix_txn_date (txn_date),
    INDEX ix_txn_cat (merchant_category)
) ENGINE=InnoDB;

CREATE TABLE campaigns (
    campaign_id         CHAR(7) PRIMARY KEY,               -- 'CMP-01'
    campaign_name       VARCHAR(100) NOT NULL,
    channel             VARCHAR(30) NOT NULL,              -- Email | In-App | Statement Insert | Direct Mail
    target_segment      VARCHAR(20) NOT NULL,
    months_active       INT NOT NULL,
    budget              DECIMAL(14,2) NOT NULL,
    impressions         INT NOT NULL,
    clicks              INT NOT NULL,
    conversions         INT NOT NULL,
    attributed_revenue  DECIMAL(16,2) NOT NULL,
    ctr                 DECIMAL(8,4) NOT NULL,
    cvr                 DECIMAL(8,4) NOT NULL,
    roas                DECIMAL(8,2) NOT NULL,
    cpa                 DECIMAL(10,2) NOT NULL,
    INDEX ix_camp_channel (channel)
) ENGINE=InnoDB;

CREATE TABLE ab_test_daily (
    date         DATE NOT NULL,
    arm          VARCHAR(10) NOT NULL,                    -- control | treatment
    impressions  INT NOT NULL,
    conversions  INT NOT NULL,
    cvr          DECIMAL(8,5) NOT NULL,
    PRIMARY KEY (date, arm)
) ENGINE=InnoDB;
